# efc.ui  (ignition/script-python/efc/ui/code.py) - EFC Library dynamic windows. Generated by generator/docks/build_docks.py.
# Ignition 8.1.19+ (Jython 2.7), 8.3 compatible. Dock strategy (decision 31, replaces 24): every dynamic window opens
# in ONE right-side Perspective dock, id DOCK_ID ('dw_Right'), which each page config defines (right, 400 x 860 at
# 1080p, display visible, content cover: always present, decision 32). openDynamic swaps the dock's view with system.perspective.alterDock, then opens it with
# system.perspective.openDock. Graph expand (decision 26) is local to Templates/Dynamic Window/Parts/Trend.
#   template symbol onClick:        efc.ui.openDynamic(self)
#   template symbol onDoubleClick:  efc.ui.dblCmd(self)
#   window close button:            efc.ui.closeDynamic(self)
#   screen root onStartup:          efc.ui.setDefaultDock(self, viewPath, params)   (optional default dock view)

# The one right-side dock every dynamic window opens in (Page Configuration dock id)
DOCK_ID = 'dw_Right'

# Dynamic-window id -> view path
WINDOWS = {
    'dw_ValveDiscrete': 'Templates/Dynamic Window/Valves/ValveDiscrete', 'dw_ValveAnalog': 'Templates/Dynamic Window/Valves/ValveAnalog',
    'dw_Rotating': 'Templates/Dynamic Window/Rotating/Rotating', 'dw_VFD': 'Templates/Dynamic Window/Rotating/VFD', 'dw_Heater': 'Templates/Dynamic Window/HeatTransfer/Heater',
    'dw_HeatTransfer': 'Templates/Dynamic Window/HeatTransfer/HeatTransfer', 'dw_ProcessValue': 'Templates/Dynamic Window/ProcessValues/ProcessValue',
    'dw_Loop': 'Templates/Dynamic Window/Loops/Loop', 'dw_Station': 'Templates/Dynamic Window/Station/Station', 'dw_IOCard': 'Templates/Dynamic Window/IO/IOCard',
}
# Template tType -> default window (a template's dockId param overrides it)
BY_TYPE = {
    'T_DValve': 'dw_ValveDiscrete', 'T_CValve': 'dw_ValveAnalog', 'T_Motor': 'dw_Rotating', 'T_VFD': 'dw_VFD',
    'T_Heater': 'dw_Heater', 'T_HeatEx': 'dw_HeatTransfer', 'T_AI': 'dw_ProcessValue', 'T_KPI': 'dw_ProcessValue',
    'T_PID': 'dw_Loop', 'T_Station': 'dw_Station', 'native': 'dw_IOCard',
}
# Role hierarchy, low to high (Controls Standard HMI rules)
ROLES = ['Guest', 'Operator', 'Maintenance', 'Supervisor', 'Engineer', 'Admin']
OPERATOR, MAINT, SUPERVISOR, ENGINEER = 1, 2, 3, 4

# Two-state devices that accept a double-tap command: type -> (state member, cmd if on, cmd if off)
DBL_CMD = {
    'T_DValve': ('Sts_Opened', 'Cmd_Close', 'Cmd_Open'),
    'T_Motor':  ('Sts_Running', 'Cmd_Stop', 'Cmd_Start'),
}
READY_TRUE = ['Mode/Sts_Man', 'Sts_Avail']
READY_FALSE = ['Sts_Intlk', 'Sts_NotPerm', 'Sts_Local', 'Sts_Fault']


def _log():
    return system.util.getLogger('efc.ui')


def _p(params, name, default=None):
    try:
        v = getattr(params, name)
    except Exception:
        try:
            v = params[name]
        except Exception:
            return default
    return default if v is None else v


def level(roles):
    """Highest role level the user holds (0 Guest .. 5 Admin). Bound by every window as custom.level."""
    best = 0
    for r in (roles or []):
        r = str(r)
        if r in ROLES:
            best = max(best, ROLES.index(r))
    return best


def userLevel(component):
    return level(component.session.props.auth.user.roles)


def _state(component):
    """This screen's dock state: {'default': {'path', 'params'}}, keyed by tab and screen (pageId survives
    navigate(), so a default set on one screen must not leak into the next)."""
    s = component.session.custom
    if getattr(s, 'efcDw', None) is None:
        s.efcDw = {}
    pid = '%s|%s' % (component.page.props.pageId, component.page.props.path)
    st = dict(s.efcDw.get(pid) or {})
    return s, pid, st


def _write(component, **changes):
    s, pid, st = _state(component)
    st.update(changes)
    d = dict(s.efcDw)
    d[pid] = st
    s.efcDw = d


def showDock(path, params=None):
    """Load a view into the right dock (DOCK_ID) on the calling page and open it."""
    params = dict(params or {})
    system.perspective.alterDock(DOCK_ID, {'view': path, 'viewParams': params})
    system.perspective.openDock(DOCK_ID, params=params)


def openWindow(dw, tagPath, model=None):
    """Open dynamic window `dw` (a WINDOWS id) for tagPath in the right dock."""
    if dw not in WINDOWS:
        _log().warn('openWindow: unknown dynamic window %s' % dw)
        return
    params = {'tagPath': tagPath or ''}
    if model:
        params['model'] = model
    showDock(WINDOWS[dw], params)


def openDynamic(component):
    """Single click on a template's symbol: open its dynamic window for this tag in the right dock."""
    p = component.view.params
    dw = _p(p, 'dockId') or BY_TYPE.get(_p(p, 'tType', ''))
    if dw not in WINDOWS:
        _log().warn('openDynamic: no window for tType=%s dockId=%s' % (_p(p, 'tType'), _p(p, 'dockId')))
        return
    tp = _p(p, 'dwTagPath') or _p(p, 'tagPath') or _p(p, 'cardPath') or ''
    openWindow(dw, tp, _p(p, 'model'))


def setDefaultDock(component, viewPath, params=None):
    """Screen onStartup (optional): remember and show the page's default right-dock view."""
    if viewPath:
        params = dict(params or {})
        _write(component, default={'path': viewPath, 'params': params})
        showDock(viewPath, params)


def closeDynamic(component):
    """Dynamic-window close button: put the page's default view back in the right dock, or close the dock."""
    s, pid, st = _state(component)
    d = st.get('default') or {}
    if d.get('path'):
        showDock(d['path'], d.get('params'))
    else:
        system.perspective.closeDock(DOCK_ID)


def _audit(component, action, target, value=''):
    user = component.session.props.auth.user.userName
    try:
        system.util.audit(action=action, actionTarget=target, actionValue=str(value), actor=user)
    except Exception:
        pass                                   # no audit profile (or older 8.1): the logger keeps the record
    _log().info('AUDIT %s %s %s by %s' % (action, target, value, user))


def cmd(component, member, value=True, minLevel=OPERATOR, audit=False):
    """Window button: write one member of the window's tag, if the user's role allows it."""
    if userLevel(component) < minLevel:
        return
    tp = component.view.params.tagPath + '/' + member
    system.tag.writeBlocking([tp], [value])
    if audit:
        _audit(component, 'EFC write', tp, value)


def bypass(component, intlkPath, idx, reason):
    """BypassConfirm popup: Supervisor+ with a reason; written to the audit log."""
    reason = (reason or '').strip()
    if userLevel(component) < SUPERVISOR or not reason:
        return False
    system.tag.writeBlocking(['%s/Cmd_Bypass/%d' % (intlkPath, idx)], [True])
    _audit(component, 'EFC bypass', '%s/%d' % (intlkPath, idx), reason)
    return True


def unbypass(component, intlkPath, idx):
    if userLevel(component) < SUPERVISOR:
        return
    system.tag.writeBlocking(['%s/Cmd_Unbypass/%d' % (intlkPath, idx)], [True])
    _audit(component, 'EFC unbypass', '%s/%d' % (intlkPath, idx))


def ackAll(component, alarms):
    """ACK button: acknowledge every unacked PLC alarm member listed (Operator+)."""
    if userLevel(component) < OPERATOR:
        return
    base = component.view.params.tagPath
    vals = system.tag.readBlocking([base + '/' + a + '/Sts_Unack' for a in alarms])
    paths = [base + '/' + a + '/Cmd_Ack' for a, q in zip(alarms, vals) if q.value]
    if paths:
        system.tag.writeBlocking(paths, [True] * len(paths))


def _num(v):
    """float(v), or None when v is missing or not numeric (so the point is skipped)."""
    try:
        return None if v is None else float(v)
    except (TypeError, ValueError):
        return None


def trend(base, pens, minutes, w, h):
    """Templates/Dynamic Window/Parts/Trend transform: SVG path per pen over the last `minutes` from tag history."""
    out = {'d': [''] * len(pens), 'lo': '', 'hi': ''}
    if not base or not pens:
        return out
    try:
        ds = system.tag.queryTagHistory(paths=[base + '/' + m for m in pens], rangeMinutes=int(minutes),
                                        returnSize=200, aggregationMode='Average', returnFormat='Wide',
                                        ignoreBadQuality=True)
    except Exception as e:
        _log().warn('trend: queryTagHistory failed for %s: %s' % (base, e))
        return out
    rows = [[_num(ds.getValueAt(r, c + 1)) for c in range(len(pens))] for r in range(ds.getRowCount())]
    vals = [v for row in rows for v in row if v is not None]
    if len(rows) < 2 or not vals:
        return out
    lo, hi = min(vals), max(vals)
    pad = max((hi - lo) * 0.1, 0.5)
    lo, hi = lo - pad, hi + pad
    n = len(rows) - 1
    for c in range(len(pens)):
        pts = ['%.1f,%.1f' % (w * i / n, h - (row[c] - lo) / (hi - lo) * h)
               for i, row in enumerate(rows) if row[c] is not None]
        out['d'][c] = ('M' + ' L'.join(pts)) if len(pts) > 1 else ''
    out['lo'], out['hi'] = '%.4g' % lo, '%.4g' % hi
    return out


def dblCmd(component):
    """Double-click/tap on the symbol in touch mode: toggle a two-state device (Operator+).
    Sent only when the template has useButton = false and dblCmd = true, the device is
    in Manual and available, and nothing blocks it."""
    p = component.view.params
    if _p(p, 'useButton') or not _p(p, 'dblCmd') or _p(p, 'tType') not in DBL_CMD or userLevel(component) < OPERATOR:
        return
    base = p.tagPath
    state, cmdOn, cmdOff = DBL_CMD[p.tType]
    paths = [base + '/' + m for m in [state] + READY_TRUE + READY_FALSE]
    v = [q.value for q in system.tag.readBlocking(paths)]
    isOn, ready = v[0], v[1:1 + len(READY_TRUE)]
    blocked = v[1 + len(READY_TRUE):]
    if not all(ready) or any(blocked):
        return
    system.tag.writeBlocking([base + '/' + (cmdOn if isOn else cmdOff)], [True])
